using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        // Breaking change #4: Sync I/O now throws by default in EF Core 9 Cosmos provider.
        // Enable sync I/O if you cannot migrate all call sites to async yet.
        // Preferred long-term fix: switch to ToListAsync / SaveChangesAsync everywhere.
        optionsBuilder.ConfigureWarnings(w =>
            w.Ignore(Microsoft.EntityFrameworkCore.Diagnostics.CosmosEventId.SyncNotSupported));
    }
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change #1: Discriminator property renamed from "Discriminator" to "$type".
        // Pin the old property name so existing documents are still found.
        modelBuilder.Entity<Blog>()
            .HasDiscriminator<string>("Discriminator");

        // Breaking change #2: Id format changed from "EntityType|Key" to just "Key".
        // Pin the old id factory so existing documents like "Blog|1" are still found.
        modelBuilder.Entity<Blog>()
            .HasPartitionKey(b => b.Id)
            .Property(b => b.Id)
            .ToJsonProperty("id");

        // Breaking change #3: HasIndex now throws for the Cosmos provider in EF Core 9.
        // Cosmos indexing is managed server-side via indexing policy, not EF model indexes.
        // REMOVED: modelBuilder.Entity<Blog>().HasIndex(b => b.Name);
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

