using Microsoft.EntityFrameworkCore;
class SyncJob
{
    // Breaking change #4: Sync I/O (ToList, SaveChanges) throws by default in EF Core 9.
    // Preferred fix: convert to async. The fallback warning suppression is in BlogContext.
    async Task RunAsync(BlogContext context)
    {
        var blogs = await context.Blogs.ToListAsync();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }
        await context.SaveChangesAsync();
    }
}

